import {ControlGroup} from '@github-ui/control-group'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {AppsIcon} from '@primer/octicons-react'
import {Button, SelectPanel} from '@primer/react'
import type {ActionListItemInput as ItemInput} from '@primer/react/deprecated'
import pluralize from 'pluralize'
import {useState} from 'react'

import type {MarketplaceAppListing, OwnerSelection} from '../types/repo-creation-types'

export function ModernMarketplaceAppsSelection({
  ownerSelection,
  manuallySelectedListingIds,
  onListingsSave,
}: {
  ownerSelection: OwnerSelection
  manuallySelectedListingIds: number[]
  onListingsSave: (listings: number[]) => void
}) {
  const {installableApps, name} = ownerSelection

  const [showDialog, setShowDialog] = useState(false)
  const [filterValue, setFilterValue] = useState('')

  const installableAppsForDialog = installableApps.map(x => listingToItemInput(x, name))
  const initiallySelectedItems = installableAppsForDialog.filter(
    x => manuallySelectedListingIds.includes(x.id as number) || x.inactiveText,
  )

  const [selectedApps, setSelectedApps] = useState(initiallySelectedItems)

  const filteredListings = filterValue
    ? installableAppsForDialog.filter(listing => listing.text?.toLowerCase().includes(filterValue.toLowerCase()))
    : installableAppsForDialog

  return (
    <>
      <ControlGroup>
        <ControlGroup.Item>
          <ControlGroup.Title className="fgColor-default">Connect GitHub Apps</ControlGroup.Title>
          <ControlGroup.Description>Connect this repository to apps {name} is subscribed to</ControlGroup.Description>
          <ControlGroup.Custom>
            {/* eslint-disable-next-line primer-react/no-system-props */}
            <SelectPanel
              variant="modal"
              title="Choose GitHub Apps"
              placeholderText="Search apps"
              renderAnchor={anchorProps => (
                <ChooseAppsButton selectedListingsCount={initiallySelectedItems.length} anchorProps={anchorProps} />
              )}
              open={showDialog}
              onOpenChange={(open, gesture) => {
                setShowDialog(open)
                if (!open && gesture === 'selection') {
                  const autoinstalledIdsSet = new Set(installableApps.filter(x => x.autoInstall).map(x => x.id))
                  const selectedIds = selectedApps.map(x => x.id as number)
                  const manuallySelectedIdsToSave = selectedIds.filter(x => !autoinstalledIdsSet.has(x))
                  onListingsSave(manuallySelectedIdsToSave)
                  setSelectedApps(selectedApps)
                }
              }}
              onCancel={() => setSelectedApps(initiallySelectedItems)}
              onFilterChange={setFilterValue}
              items={filteredListings}
              selected={selectedApps}
              onSelectedChange={setSelectedApps}
              width="large"
              height={filteredListings.length >= 10 ? 'xlarge' : 'auto'}
              message={
                filteredListings.length === 0
                  ? {
                      title: `No apps found for \`${filterValue}\``,
                      variant: 'empty',
                      body: 'Adjust your search term to find other apps',
                    }
                  : undefined
              }
            />
          </ControlGroup.Custom>
        </ControlGroup.Item>
      </ControlGroup>
    </>
  )
}

function ChooseAppsButton({
  selectedListingsCount,
  anchorProps,
}: {
  selectedListingsCount: number
  anchorProps: React.HTMLAttributes<HTMLElement>
}) {
  if (selectedListingsCount > 0) {
    return (
      <Button leadingVisual={<AppsIcon />} {...anchorProps}>
        {`${selectedListingsCount} ${pluralize('app', selectedListingsCount)} selected`}
      </Button>
    )
  }

  return <Button {...anchorProps}>Choose apps</Button>
}

type Items = ItemInput & {
  inactiveText?: string
}

const listingToItemInput = (listing: MarketplaceAppListing, orgName: string): Items => {
  const {id, normalizedShortDescription, autoInstall, bgcolor, name, primaryAvatarUrl} = listing

  return {
    leadingVisual: () => (
      <GitHubAvatar
        square
        src={primaryAvatarUrl}
        style={{backgroundColor: `#${bgcolor}`, padding: 'var(--base-size-2)'}}
      />
    ),
    text: name,
    description: normalizedShortDescription,
    descriptionVariant: 'block',
    id,
    inactiveText: autoInstall ? `Auto-installed by ${orgName}` : undefined,
  }
}

try{ ModernMarketplaceAppsSelection.displayName ||= 'ModernMarketplaceAppsSelection' } catch {}
try{ ChooseAppsButton.displayName ||= 'ChooseAppsButton' } catch {}