import {Button} from '@primer/react'

import styles from './RepoNameGenerator.module.css'

export function ModernRepoNameGenerator({
  suggestedRepoName,
  onClick,
}: {
  suggestedRepoName: string
  onClick: (suggestedName: string) => void
}) {
  return (
    <div className="my-3">
      Great repository names are short and memorable. How about&nbsp;
      <span className={styles.noWrap}>
        <Button
          variant="link"
          className="fgColor-success"
          aria-label={`Use suggested repository name ${suggestedRepoName}`}
          onClick={() => onClick(suggestedRepoName)}
        >
          {suggestedRepoName}
        </Button>
        ?
      </span>
    </div>
  )
}

try{ ModernRepoNameGenerator.displayName ||= 'ModernRepoNameGenerator' } catch {}